import { useMemo, useState } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import * as THREE from 'three'

const SKY = '#f4d9c6'
const GOLD = '#d4a93a'
const VELVET = '#8a1a36'

function Gold(props) {
  return <meshStandardMaterial color={GOLD} metalness={0.4} roughness={0.35} emissive="#6b4e0a" {...props} />
  }

  let glowTex
  function getGlow() {
    if (!glowTex) {
        const c = document.createElement('canvas')
            c.width = c.height = 128
                const g = c.getContext('2d')
                    const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64)
                        grd.addColorStop(0, 'rgba(255,236,170,0.95)')
                            grd.addColorStop(0.4, 'rgba(255,220,140,0.35)')
                                grd.addColorStop(1, 'rgba(255,220,140,0)')
                                    g.fillStyle = grd
                                        g.fillRect(0, 0, 128, 128)
                                            glowTex = new THREE.CanvasTexture(c)
                                              }
                                                return glowTex
                                                }

                                                function Floor() {
                                                  const tex = useMemo(() => {
                                                      const c = document.createElement('canvas')
                                                          c.width = c.height = 128
                                                              const g = c.getContext('2d')
                                                                  g.fillStyle = '#f6eee2'
                                                                      g.fillRect(0, 0, 128, 128)
                                                                          g.fillStyle = '#2b2226'
                                                                              g.fillRect(0, 0, 64, 64)
                                                                                  g.fillRect(64, 64, 64, 64)
                                                                                      const t = new THREE.CanvasTexture(c)
                                                                                          t.wrapS = t.wrapT = THREE.RepeatWrapping
                                                                                              t.repeat.set(6, 10)
                                                                                                  return t
                                                                                                    }, [])
                                                                                                      return (
                                                                                                          <>
                                                                                                                <mesh rotation-x={-Math.PI / 2} position={[0, 0, -5]}>
                                                                                                                        <planeGeometry args={[18, 30]} />
                                                                                                                                <meshStandardMaterial map={tex} roughness={0.2} metalness={0.1} />
                                                                                                                                      </mesh>
                                                                                                                                            <mesh rotation-x={-Math.PI / 2} position={[0, 0.01, -4]}>
                                                                                                                                                    <circleGeometry args={[3, 48]} />
                                                                                                                                                            <meshStandardMaterial color={VELVET} emissive="#3a0a18" />
                                                                                                                                                                  </mesh>
                                                                                                                                                                        <mesh rotation-x={-Math.PI / 2} position={[0, 0.02, -4]}>
                                                                                                                                                                                <ringGeometry args={[2.9, 3.1, 48]} />
                                                                                                                                                                                        <meshBasicMaterial color={GOLD} />
                                                                                                                                                                                              </mesh>
                                                                                                                                                                                                  </>
                                                                                                                                                                                                    )
                                                                                                                                                                                                    }

                                                                                                                                                                                                    function Shell() {
                                                                                                                                                                                                      const wall = <meshStandardMaterial color="#ecd8bc" roughness={0.9} />
                                                                                                                                                                                                        return (
                                                                                                                                                                                                            <>
                                                                                                                                                                                                                  <mesh position={[0, 5, -15]}>
                                                                                                                                                                                                                          <boxGeometry args={[18, 10, 0.5]} />
                                                                                                                                                                                                                                  {wall}
                                                                                                                                                                                                                                        </mesh>
                                                                                                                                                                                                                                              {[-1, 1].map((s) => (
                                                                                                                                                                                                                                                      <mesh key={s} position={[s * 9, 5, -5]}>
                                                                                                                                                                                                                                                                <boxGeometry args={[0.5, 10, 30]} />
                                                                                                                                                                                                                                                                          {wall}
                                                                                                                                                                                                                                                                                  </mesh>
                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                              <mesh rotation-x={Math.PI / 2} position={[0, 10, -5]}>
                                                                                                                                                                                                                                                                                                      <planeGeometry args={[18, 30]} />
                                                                                                                                                                                                                                                                                                              <meshStandardMaterial color="#f8ecda" />
                                                                                                                                                                                                                                                                                                                    </mesh>
                                                                                                                                                                                                                                                                                                                          <mesh position={[0, 6, -14.7]}>
                                                                                                                                                                                                                                                                                                                                  <planeGeometry args={[3.6, 5]} />
                                                                                                                                                                                                                                                                                                                                          <meshBasicMaterial color="#fff6dc" />
                                                                                                                                                                                                                                                                                                                                                </mesh>
                                                                                                                                                                                                                                                                                                                                                      <mesh position={[0, 8.6, -14.6]}>
                                                                                                                                                                                                                                                                                                                                                              <boxGeometry args={[4, 0.2, 0.2]} />
                                                                                                                                                                                                                                                                                                                                                                      <Gold />
                                                                                                                                                                                                                                                                                                                                                                            </mesh>
                                                                                                                                                                                                                                                                                                                                                                                </>
                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                  function Stairs({ side }) {
                                                                                                                                                                                                                                                                                                                                                                                    const x = side * 5.2
                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                          <group>
                                                                                                                                                                                                                                                                                                                                                                                                {Array.from({ length: 9 }).map((_, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                        <group key={i}>
                                                                                                                                                                                                                                                                                                                                                                                                                  <mesh position={[x, ((i + 1) * 0.4) / 2, -2 - i]}>
                                                                                                                                                                                                                                                                                                                                                                                                                              <boxGeometry args={[3.2, (i + 1) * 0.4, 1]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                          <meshStandardMaterial color="#f7efe3" roughness={0.4} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                    </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <mesh position={[x, (i + 1) * 0.4 + 0.01, -2 - i]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <boxGeometry args={[1.4, 0.02, 1]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <meshStandardMaterial color={VELVET} emissive="#3a0a18" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <mesh position={[x + side * 1.55, (i + 1) * 0.4 + 0.4, -2 - i]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <cylinderGeometry args={[0.04, 0.04, 0.8, 6]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Gold />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <mesh position={[x + side * 1.55, 2.8, -6]} rotation-x={0.3805}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <boxGeometry args={[0.1, 0.1, 8.62]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Gold />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <mesh position={[x, 1.8, -12.5]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <boxGeometry args={[3.2, 3.6, 4]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <meshStandardMaterial color="#f7efe3" roughness={0.4} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <mesh position={[x, 5, -14.7]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <planeGeometry args={[1.8, 2.8]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <meshBasicMaterial color="#fff6dc" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function BigChandelier() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <group position={[0, 7.2, -4]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <mesh position={[0, 1.4, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <cylinderGeometry args={[0.03, 0.03, 2.8, 6]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Gold />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {[1.7, 1.1].map((r, k) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <mesh key={r} position={[0, -k * 0.7, 0]} rotation-x={Math.PI / 2}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <torusGeometry args={[r, 0.06, 8, 32]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Gold />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {Array.from({ length: 20 }).map((_, i) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const a = (i / 20) * Math.PI * 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <mesh key={i} position={[Math.cos(a) * 1.7, -0.3, Math.sin(a) * 1.7]} rotation-x={Math.PI}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <coneGeometry args={[0.08, 0.35, 5]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <meshBasicMaterial color="#fffbe8" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <sprite scale={[9, 9, 1]} position={[0, -0.4, 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <spriteMaterial map={getGlow()} transparent depthWrite={false} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </sprite>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <pointLight intensity={60} distance={30} color="#ffd9a0" position={[0, -1, 0]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function Rig({ phase, side, onReady, onArrive }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const ready = { current: false }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          useFrame((state, dt) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const cam = state.camera
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const t = state.clock.elapsedTime
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (phase === 'enter' || phase === 'choose') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cam.position.z = THREE.MathUtils.damp(cam.position.z, 4, 1.1, dt)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cam.position.y = 1.7 + Math.sin(t) * 0.01
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (phase === 'enter' && cam.position.z < 4.3) onReady()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else if (phase === 'climb') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const tx = side * 5.2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cam.position.x = THREE.MathUtils.damp(cam.position.x, tx, 2.2, dt)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (Math.abs(cam.position.x - tx) < 0.35) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cam.position.z = THREE.MathUtils.damp(cam.position.z, -10.2, 0.7, dt)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cam.position.y = 1.7 + THREE.MathUtils.clamp(-1.5 - cam.position.z, 0, 9) * 0.4 + Math.sin(t * 2) * 0.02
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (cam.position.z < -9.4) onArrive()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                export default function Hall({ done, onChoose, onFinale }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const [phase, setPhase] = useState('enter')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const [side, setSide] = useState(-1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const all = done.left === 3 && done.right === 3

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const go = (s) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (phase !== 'choose') return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setSide(s)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setPhase('climb')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="stage">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Canvas dpr={[1, 1.5]} camera={{ position: [0, 1.7, 9], fov: 62 }} gl={{ antialias: true, powerPreference: 'high-performance' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <color attach="background" args={[SKY]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <fog attach="fog" args={[SKY, 14, 50]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <ambientLight intensity={1.0} color="#fff0d6" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <hemisphereLight args={['#fff4e0', '#e7b9a0', 0.9]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Rig
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    phase={phase}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              side={side}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onReady={() => setPhase((p) => (p === 'enter' ? 'choose' : p))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onArrive={() => onChoose(side === -1 ? 'left' : 'right')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Floor />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Shell />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <BigChandelier />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Stairs side={-1} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Stairs side={1} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Canvas>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {phase === 'choose' && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="overlay" key="choose">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="kicker">THE GRAND HALL</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="hint">Two staircases. Which way will you go, my king?</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="hall-btns">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button className="gold-btn" onClick={() => go(-1)}>◀ LEFT<small>Heart Wing {done.left}/3</small></button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button className="gold-btn" onClick={() => go(1)}>RIGHT ▶<small>Royal Wing {done.right}/3</small></button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {all && <button className="gold-btn glow" onClick={onFinale}>THE BALCONY</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }